package com.xxl.core.data.model.entity.pay;import android.text.TextUtils;import java.util.Map;/** * 支付宝支付结果 * * @author xxl. * @date 2024/04/17. */public class AliPayResult {    private String resultStatus;    private String result;    private String memo;    public AliPayResult(Map<String, String> rawResult) {        if (rawResult == null) {            return;        }        for (String key : rawResult.keySet()) {            if (TextUtils.equals(key, "resultStatus")) {                resultStatus = rawResult.get(key);            } else if (TextUtils.equals(key, "result")) {                result = rawResult.get(key);            } else if (TextUtils.equals(key, "memo")) {                memo = rawResult.get(key);            }        }    }    @Override    public String toString() {        return "resultStatus={" + resultStatus + "};memo={" + memo                + "};result={" + result + "}";    }    /**     * 该笔订单是否真实支付成功，需要依赖服务端的异步通知。     *     * @return payment success     */    public boolean isSuccess() {        return TextUtils.equals(resultStatus, PAY_CODE_SUCCESS);    }    /**     * 该笔订单是否真实支付成功，需要依赖服务端的异步通知。     *     * @return payment cancel     */    public boolean isCancel() {        return TextUtils.equals(resultStatus, PAY_CODE_CANCEL);    }    /**     * 该笔订单是否真实支付成功，需要依赖服务端的异步通知。     *     * @return payment failure     */    public boolean isFailure() {        return TextUtils.equals(resultStatus, PAY_CODE_FAIL);    }    /**     * @return the resultStatus     */    public String getResultStatus() {        return resultStatus;    }    /**     * @return the memo     */    public String getMemo() {        return memo;    }    /**     * @return the result     */    public String getResult() {        return result;    }    /**     * 支付成功     */    public static final String PAY_CODE_SUCCESS = "9000";    /**     * 支付失败     */    public static final String PAY_CODE_FAIL = "4000";    /**     * 用户中途取消     */    public static final String PAY_CODE_CANCEL = "6001";}